"""Compare the OpenAPI document generated by the Go server (Huma) with the shared
T003 contract. Usage: python scripts/contracts/compare.py [generated.json]

Without an argument the script runs `go run ./cmd/ctl openapi` in apps/server.
Exit status is nonzero when the generated API disagrees with the contract in a
way not listed in DEVIATIONS. DEVIATIONS are intentional, policy-compatible
differences that are documented in handoffs/T003.md.
"""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CONTRACT = json.loads((ROOT / 'contracts' / 't003' / 'openapi.json').read_text(encoding='utf-8'))

if len(sys.argv) > 1:
    GENERATED = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
else:
    out = subprocess.run(['go', 'run', './cmd/ctl', 'openapi'], cwd=ROOT / 'apps' / 'server', check=True,
                         capture_output=True, text=True).stdout
    GENERATED = json.loads(out)

# Intentional differences. Key: where, value: reason.
DEVIATIONS = {
    'UpdateUser.minProperties': 'enforced by the handler (422 validation_failed); Huma has no minProperties tag',
    'Problem.additionalProperties': 'Problem is a closed typed struct in Huma; the contract leaves it open',
}

errors, notes = [], []


def ref_name(ref):
    return ref.rsplit('/', 1)[-1]


def resolve(spec, schema):
    while isinstance(schema, dict) and '$ref' in schema:
        schema = spec['components']['schemas'][ref_name(schema['$ref'])]
    return schema


IGNORED = {'description', 'title', 'examples', 'example', '$schema', 'default', 'readOnly', 'x-', 'contentEncoding'}


def norm(spec, schema, depth=0):
    """Reduce a schema to a comparable structure; $ref names are kept for objects."""
    if schema is None:
        return None
    ref = ref_name(schema['$ref']) if isinstance(schema, dict) and '$ref' in schema else None
    s = resolve(spec, schema)
    out = {}
    nullable = bool(s.get('nullable'))
    if 'anyOf' in s:
        non_null = [x for x in s['anyOf'] if resolve(spec, x).get('type') != 'null']
        has_null = len(non_null) != len(s['anyOf'])
        if has_null and len(non_null) == 1:
            inner = norm(spec, non_null[0], depth)
            inner['nullable'] = True
            return inner
        out['anyOf'] = [norm(spec, x, depth + 1) for x in s['anyOf']]
    t = s.get('type')
    if isinstance(t, list):
        if 'null' in t:
            nullable = True
        t = [x for x in t if x != 'null']
        t = t[0] if len(t) == 1 else t
    if t:
        out['type'] = t
    if nullable:
        out['nullable'] = True
    if 'const' in s:
        out['enum'] = [s['const']]
    if 'enum' in s:
        out['enum'] = sorted(x for x in s['enum'] if x is not None)
    for k in ('format', 'pattern', 'minimum', 'maximum', 'minLength', 'maxLength', 'minItems', 'minProperties'):
        if k in s:
            out[k] = s[k]
    if out.get('format') in ('int64', 'int32', 'double', 'float'):
        del out['format']
    if 'properties' in s:
        out['properties'] = {k: norm(spec, v, depth + 1) for k, v in s['properties'].items()}
        out['required'] = sorted(s.get('required', []))
        out['additionalProperties'] = s.get('additionalProperties', None)
    if 'items' in s:
        out['items'] = norm(spec, s['items'], depth + 1)
    if ref and depth > 0:
        out['$name'] = ref
    return out


def compare(path, want, got):
    """The contract (want) decides which keys matter; extra generated keys are tolerated."""
    if want is None:
        return
    if got is None:
        errors.append(f'{path}: missing in generated spec')
        return
    for k, v in want.items():
        if k == '$name':
            continue
        if k == 'additionalProperties':
            if v is False and got.get(k) is not False:
                errors.append(f'{path}: contract forbids extra properties, generated allows them')
            elif v in (True, None) and got.get(k) is False and path.split('.')[0] + '.additionalProperties' not in DEVIATIONS:
                errors.append(f'{path}: generated forbids extra properties, contract allows them')
            continue
        if k == 'minProperties' and path + '.minProperties' in DEVIATIONS or (k == 'minProperties' and path.split('.')[0] + '.minProperties' in DEVIATIONS):
            continue
        if k == 'properties':
            if set(v) != set(got.get('properties', {})):
                errors.append(f'{path}: properties differ: contract-only={sorted(set(v) - set(got.get("properties", {})))} generated-only={sorted(set(got.get("properties", {})) - set(v))}')
            for name, sub in v.items():
                compare(f'{path}.{name}', sub, got.get('properties', {}).get(name))
        elif k == 'items':
            compare(path + '[]', v, got.get('items'))
        elif k == 'anyOf':
            if len(v) != len(got.get('anyOf', [])):
                errors.append(f'{path}: anyOf arity differs')
        elif k == 'required':
            if v != got.get('required', []):
                errors.append(f'{path}: required differs: contract={v} generated={got.get("required", [])}')
        elif k == 'nullable':
            if not got.get('nullable'):
                errors.append(f'{path}: contract allows null, generated does not')
        else:
            if got.get(k) != v:
                errors.append(f'{path}.{k}: contract={v!r} generated={got.get(k)!r}')


# ---- component schemas -------------------------------------------------------
for name, schema in CONTRACT['components']['schemas'].items():
    if name not in GENERATED['components']['schemas']:
        errors.append(f'schema {name}: missing in generated spec')
        continue
    compare(name, norm(CONTRACT, {'$ref': f'#/components/schemas/{name}'}), norm(GENERATED, {'$ref': f'#/components/schemas/{name}'}))
extra = sorted(set(GENERATED['components']['schemas']) - set(CONTRACT['components']['schemas']))
if extra:
    notes.append(f'generated-only schemas (inline/helper types): {extra}')


# ---- operations -----------------------------------------------------------------
def operations(spec):
    ops = {}
    for p, item in spec['paths'].items():
        for m, o in item.items():
            if m in ('parameters', 'summary', 'description', 'servers'):
                continue
            ops[o['operationId']] = (m.upper(), p, o)
    return ops


want_ops, got_ops = operations(CONTRACT), operations(GENERATED)
for oid in sorted(set(want_ops) - set(got_ops)):
    errors.append(f'operation {oid}: missing in generated spec')
for oid in sorted(set(got_ops) - set(want_ops)):
    errors.append(f'operation {oid}: not in the contract (unexpected route)')


def strip_prefix(path):
    return path[len('/api/v1'):] if path.startswith('/api/v1/') else path


def body_schema(spec, op):
    c = op.get('requestBody', {}).get('content', {})
    for mt in c.values():
        s = mt.get('schema')
        return ref_name(s['$ref']) if s and '$ref' in s else json.dumps(s, sort_keys=True)
    return None


def response_schema(spec, op, code):
    r = op.get('responses', {}).get(code)
    if not r:
        return None
    for mt in r.get('content', {}).values():
        s = mt.get('schema')
        if s and '$ref' in s:
            return ref_name(s['$ref'])
        return json.dumps({k: v for k, v in (s or {}).items() if k in ('type', 'format')}, sort_keys=True)
    return ''


def params(spec, op, item):
    out = {}
    for prm in list(op.get('parameters', [])) + list(item.get('parameters', [])):
        prm = prm if '$ref' not in prm else spec['components']['parameters'][ref_name(prm['$ref'])]
        out[(prm['in'], prm['name'])] = bool(prm.get('required'))
    return out


for oid in sorted(set(want_ops) & set(got_ops)):
    wm, wp, wo = want_ops[oid]
    gm, gp, go = got_ops[oid]
    if wm != gm or wp != strip_prefix(gp):
        errors.append(f'{oid}: {wm} {wp} vs generated {gm} {gp}')
    if body_schema(CONTRACT, wo) != body_schema(GENERATED, go):
        errors.append(f'{oid}: request body {body_schema(CONTRACT, wo)} vs {body_schema(GENERATED, go)}')
    wprm = params(CONTRACT, wo, CONTRACT['paths'][wp])
    gprm = params(GENERATED, go, GENERATED['paths'][gp])
    for k, req in wprm.items():
        if k not in gprm:
            errors.append(f'{oid}: parameter {k} missing')
        elif req and not gprm[k]:
            errors.append(f'{oid}: parameter {k} must be required')
    for k in set(gprm) - set(wprm):
        errors.append(f'{oid}: generated-only parameter {k}')
    for code in wo['responses']:
        if code not in go['responses'] and 'default' not in go['responses']:
            errors.append(f'{oid}: response {code} not declared')
            continue
        if code.startswith('2') and code in go['responses']:
            if response_schema(CONTRACT, wo, code) != response_schema(GENERATED, go, code):
                errors.append(f'{oid}: {code} schema {response_schema(CONTRACT, wo, code)} vs {response_schema(GENERATED, go, code)}')
    if (wo.get('security') or None) and not go.get('security') and not GENERATED.get('security'):
        errors.append(f'{oid}: security requirement missing')

# security schemes
for name, scheme in CONTRACT['components']['securitySchemes'].items():
    if GENERATED['components'].get('securitySchemes', {}).get(name, {}).get('type') != scheme['type']:
        errors.append(f'security scheme {name} differs')

print(f'compared {len(want_ops)} operations and {len(CONTRACT["components"]["schemas"])} schemas')
for k, v in DEVIATIONS.items():
    print(f'  intentional deviation {k}: {v}')
for n in notes:
    print('  note:', n)
if errors:
    print(f'{len(errors)} difference(s):')
    for e in errors:
        print('  -', e)
    sys.exit(1)
print('OPENAPI PARITY OK')
